/**
 * The evidence commitment, computed off-chain exactly as the contract computes it on-chain.
 *
 * A researcher commits to the CLEANED TEXT of their evidence page (sha256 of the first 8,000 characters after markup is
 * stripped from real HTML). The jury later fetches the page itself and compares. This file mirrors `clean_page` and
 * `content_hash` in contracts/mandate.py rule for rule; every character class is ASCII-defined so the two languages
 * cannot disagree. tests/vectors/fingerprint.json is generated by the contract and asserted here and in Python.
 */

export const EVIDENCE_CHARS = 8000;

const TAG_RE = /<(script|style)(?![A-Za-z0-9_]).*?<\/\1[ \t\n\r\f\v]*>|<[^>]+>/gis;
const SPACE_RE = /[ \t\r\f\v]+/g;
const BLANKS_RE = /\n(?:[ \t\r\f\v]*\n)+/g;
const EDGE_RE = /^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g;

const codePoints = (s: string, n: number): string => {
  // Python slices by code point; JS strings are UTF-16, so truncate by code point as well.
  if (s.length <= n) return s;
  let out = "";
  let i = 0;
  for (const ch of s) {
    if (i++ >= n) break;
    out += ch;
  }
  return out;
};

function looksLikeHtml(contentType: string | null | undefined, text: string): boolean {
  if (contentType) return contentType.toLowerCase().includes("html");
  const head = codePoints(text, 1000).toLowerCase();
  return head.includes("<!doctype html") || head.includes("<html");
}

/** Byte-for-byte the contract's `clean_page`. `contentType` is the response header, when there is one. */
export function cleanPage(body: Uint8Array, contentType?: string | null, limit = EVIDENCE_CHARS): string {
  let text = new TextDecoder("utf-8", { ignoreBOM: true }).decode(body);
  if (looksLikeHtml(contentType, text)) text = text.replace(TAG_RE, " ");
  text = text.split("<<<").join("< < <").split(">>>").join("> > >");
  text = text.replace(SPACE_RE, " ").replace(BLANKS_RE, "\n").replace(EDGE_RE, "");
  return codePoints(text, limit);
}

/** sha256 (hex) of the cleaned text, UTF-8: the value passed to `propose`. */
export async function contentHash(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export interface Fingerprint {
  hash: string;
  text: string;
  chars: number;
}

export async function fingerprintBytes(body: Uint8Array, contentType?: string | null): Promise<Fingerprint> {
  const text = cleanPage(body, contentType);
  if (text === "") throw new Error("That page is empty once markup is removed, so there is nothing to commit to.");
  return { hash: await contentHash(text), text, chars: [...text].length };
}

/** Fetch a public page the way a validator would (plain GET) and fingerprint it. Browsers may refuse cross-origin reads. */
export async function fingerprintUrl(url: string, fetcher: typeof fetch = fetch): Promise<Fingerprint> {
  let res: Response;
  try {
    res = await fetcher(url, { redirect: "follow", credentials: "omit" });
  } catch {
    throw new Error("This browser could not read that page (the site does not allow cross-origin reads). Run `npm run fingerprint -- <url>` and paste the result.");
  }
  if (res.status !== 200) throw new Error(`That page answered HTTP ${res.status}. The jury needs a page that loads.`);
  return fingerprintBytes(new Uint8Array(await res.arrayBuffer()), res.headers.get("content-type"));
}

export const isHash = (s: string): boolean => /^[0-9a-f]{64}$/.test(s);
